#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Parse .env file and return key-value pairs
 * @param {string} filePath - Path to .env file
 * @returns {Object} Environment variables as key-value pairs
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const content = fs.readFileSync(filePath, 'utf-8');
  const envVars = {};

  content.split('\n').forEach(line => {
    // Skip empty lines and comments
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) {
      return;
    }

    // Parse KEY=value format
    const separatorIndex = trimmed.indexOf('=');
    if (separatorIndex > 0) {
      const key = trimmed.substring(0, separatorIndex).trim();
      let value = trimmed.substring(separatorIndex + 1).trim();

      // Remove surrounding quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }

      envVars[key] = value;
    }
  });

  return envVars;
}

/**
 * Resolve database connection string from .env.test
 * @returns {string|null} Database URL or null if not found
 */
function resolveConnectionString() {
  const envVars = parseEnvFile(ENV_FILE);

  if (!envVars.DATABASE_URL) {
    console.warn('Warning: DATABASE_URL not found in .env.test');
    return null;
  }

  return envVars.DATABASE_URL;
}

/**
 * Connect to database (simulated - just logs connection)
 * @param {string} connectionString - Database connection string
 */
function connectToDatabase(connectionString) {
  // Parse connection string to display info (safely)
  let connectionInfo = 'unknown';
  try {
    const url = new URL(connectionString);
    connectionInfo = `${url.protocol}//${url.hostname}:${url.port || 'default'}${url.pathname}`;
  } catch {
    connectionInfo = '(connection string parsed)';
  }

  console.log('Successfully connected to database!');
  console.log(`Connection: ${connectionInfo}\n`);
}

/**
 * Get list of SQL migration files sorted alphabetically
 * @returns {string[]} Array of SQL filenames
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error('Error: Migrations directory does not exist:', MIGRATIONS_DIR);
    process.exit(1);
  }

  // Read all files from migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files and sort alphabetically for consistent ordering
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  return sqlFiles;
}

/**
 * Main migration function
 */
function runMigrations() {
  console.log('Starting migration process...\n');

  // Resolve and log database connection
  console.log('Resolving database connection...');
  console.log(`Reading .env.test from: ${ENV_FILE}`);

  const connectionString = resolveConnectionString();

  if (connectionString) {
    connectToDatabase(connectionString);
  } else {
    console.log('Proceeding without database connection.\n');
  }

  console.log(`Migrations directory: ${MIGRATIONS_DIR}`);
  console.log('========================================\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s) to apply:\n`);

  // Log each filename in order
  migrationFiles.forEach((filename, index) => {
    console.log(`[${index + 1}] ${filename}`);
  });

  console.log('\n========================================');
  console.log('Migration process complete.');
}

// Run the migration script
runMigrations();

