  return env;
}

/**
 * Load environment variables from .env.test and resolve DATABASE_URL
 * @returns {string|null} Database connection string or null
 */
function resolveDatabaseUrl() {
  console.log('Loading environment from .env.test...');

  const env = parseEnvFile(ENV_FILE);
  const databaseUrl = env.DATABASE_URL || process.env.DATABASE_URL;

  if (!databaseUrl) {
    console.error('ERROR: DATABASE_URL not found in .env.test or environment');
    return null;
  }

  // Parse the connection string for logging (safely)
