#!/usr/bin/env node

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 * Reads DATABASE_URL from .env.test for connection string resolution.
 */

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Parse .env file and return key-value pairs
 * @param {string} filePath - Path to .env file
 * @returns {Object} Environment variables as key-value pairs
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const env = {};

  content.split('\n').forEach(line => {
    // Trim whitespace
    line = line.trim();

    // Skip empty lines and comments
    if (!line || line.startsWith('#')) {
      return;
    }

    // Parse key=value
    const separatorIndex = line.indexOf('=');
    if (separatorIndex > 0) {
      const key = line.substring(0, separatorIndex).trim();
      const value = line.substring(separatorIndex + 1).trim();
      env[key] = value;
    }
  });

  return env;
}

/**
 * Resolve connection string from .env.test
 * @returns {string|null} Database connection string or null
 */
function resolveConnectionString() {
  const envVars = parseEnvFile(ENV_FILE);
  return envVars.DATABASE_URL || null;
}

/**
 * Parse connection string to extract components (for logging purposes)
 * @param {string} connectionString - Database connection string
 * @returns {Object} Parsed connection details (with password masked)
 */
function parseConnectionString(connectionString) {
  try {
    // Parse format: postgres://user:password@host:port/database
    const url = new URL(connectionString);
    return {
      protocol: url.protocol.replace(':', ''),
      host: url.hostname,
      port: url.port || '5432',
      database: url.pathname.replace('/', ''),
      user: url.username,
      // Mask password for security
      hasPassword: url.password ? true : false,
    };
  } catch (error) {
    return null;
  }
}

