 * Parse DATABASE_URL and return connection details
 * @param {string} databaseUrl - The database connection string
 * @returns {Object} Parsed connection details
 */
function parseDatabaseUrl(databaseUrl) {
  // Basic parsing for common database URL format:
  // postgres://user:password@host:port/database
  const regex = /^(.+):\/\/(.+):(.+)@(.+):(\d+)\/(.+)$/;
  const match = databaseUrl.match(regex);

  if (match) {
    return {
      protocol: match[1],
      user: match[2],
      password: match[3],
      host: match[4],
      port: match[5],
      database: match[6]
    };
  }

  return { raw: databaseUrl };
}

