/**
 * Load environment variables from a .env file
 * @param {string} filePath - Path to the .env file
 * @returns {object} - Parsed environment variables
 */
function loadEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return null;
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  content.split('\n').forEach(line => {
    const trimmed = line.trim();
    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      return;
    }
    // Parse KEY=value format
    const match = trimmed.match(/^([^=]+)=(.*)$/);
    if (match) {
      const key = match[1].trim();
      let value = match[2].trim();
      // Remove surrounding quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }
      envVars[key] = value;
    }
  });

  return envVars;
}

/**
 * Resolve and validate the database connection string
 * @returns {string|null} - The connection string or null if not found
 */
function resolveConnectionString() {
  // Load from .env.test file
  const envVars = loadEnvFile(ENV_FILE);

  if (!envVars) {
    console.error(`Error: Could not find ${ENV_FILE}`);
    return null;
  }

  const databaseUrl = envVars.DATABASE_URL;

  if (!databaseUrl) {
    console.error('Error: DATABASE_URL not found in .env.test');
    return null;
  }

  return databaseUrl;
}

