#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of SQL filenames, sorted in order
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    console.error('Please create a ./migrations/ directory and add SQL migration files.');
    process.exit(1);
  }

  // Read all files from the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files only
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in ./migrations/');
    return [];
  }

  // Sort files alphabetically to ensure consistent ordering
  // Convention: use timestamp prefixes like 001_, 002_, etc.
  return sqlFiles.sort();
}

/**
 * Run migrations - logs each filename that would be applied
 */
function runMigrations() {
  console.log('Starting migration process...\n');
  console.log(`Migrations directory: ${MIGRATIONS_DIR}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migrations to apply.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration(s) to apply:\n`);

  migrationFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const fileNumber = index + 1;

    console.log(`[${fileNumber}/${migrationFiles.length}] Would apply migration: ${file}`);

    // Read and log the SQL content (for demonstration)
    const sqlContent = fs.readFileSync(filePath, 'utf8').trim();
    if (sqlContent) {
      console.log(`    Content preview: ${sqlContent.split('\n')[0].substring(0, 60)}${sqlContent.split('\n')[0].length > 60 ? '...' : ''}`);
    }
    console.log();
  });

  console.log('Migration process complete.');
  console.log(`Total migrations that would be applied: ${migrationFiles.length}`);
}

// Run the migration script
runMigrations();

